'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useAuthStore } from '@/store/auth';
import type { Lead } from '@crm/types';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';

const statusV = { new:'blue', qualified:'green', proposal:'orange', converted:'purple', lost:'gray' } as const;
const statusL = { new:'Новый', qualified:'Квалифицирован', proposal:'Предложение', converted:'Конвертирован', lost:'Потерян' } as const;
const srcV    = { website:'blue', referral:'green', cold:'orange', event:'purple', inbound:'gray', '':'gray' } as const;
const srcL: Record<string, string> = { website:'Сайт', referral:'Реферал', cold:'Холодный', event:'Мероприятие', inbound:'Входящий' };

export default function LeadsPage() {
  const user = useAuthStore(s => s.user);
  const qc   = useQueryClient();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name:'', contact:'', phone:'', email:'', product:'', source:'inbound', status:'new', manager: user?.name ?? '' });

  const { data: leads = [], isLoading } = useQuery<Lead[]>({
    queryKey: ['leads'],
    queryFn:  () => api.get('/leads'),
  });

  const create = useMutation({
    mutationFn: (body: typeof form) => api.post('/leads', body),
    onSuccess: () => { qc.invalidateQueries({ queryKey:['leads'] }); setOpen(false); },
  });

  const counts = {
    new:       leads.filter(l => l.status === 'new').length,
    qualified: leads.filter(l => l.status === 'qualified').length,
    proposal:  leads.filter(l => l.status === 'proposal').length,
    lost:      leads.filter(l => l.status === 'lost').length,
  };

  if (isLoading) return <div className="flex items-center justify-center h-64 text-gray-400 text-sm">Загрузка...</div>;

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <div>
          <h2 className="text-2xl font-extrabold tracking-tight">Лиды</h2>
          <p className="text-sm text-gray-400 mt-0.5">{leads.length} всего · {counts.new} новых · {counts.qualified} квалифицировано</p>
        </div>
        <Button onClick={() => setOpen(true)}>+ Новый лид</Button>
      </div>

      <div className="grid grid-cols-4 gap-3 mb-5">
        {([['new','Новые','bg-blue-50 border-blue-100'],['qualified','Квалифицировано','bg-green-50 border-green-100'],['proposal','Предложение','bg-amber-50 border-amber-100'],['lost','Потеряно','bg-gray-50 border-gray-100']] as const).map(([k,l,cls])=>(
          <div key={k} className={`border rounded-xl p-4 ${cls}`}>
            <div className="text-2xl font-extrabold">{counts[k]}</div>
            <div className="text-sm text-gray-500">{l}</div>
          </div>
        ))}
      </div>

      <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {['Компания/Имя','Контакт','Продукт','Источник','Статус','Менеджер','Создан'].map(h => (
                  <th key={h} className="text-left px-4 py-2.5 text-[11px] font-semibold uppercase tracking-wider text-gray-400">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {leads.map(l => (
                <tr key={l.id} className="border-b border-gray-100 last:border-0 hover:bg-gray-50 transition-colors">
                  <td className="px-4 py-3 text-sm font-semibold">{l.name}</td>
                  <td className="px-4 py-3">
                    <div className="text-sm">{l.contact || '—'}</div>
                    <div className="text-xs text-gray-400">{l.phone}</div>
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-600">{l.product || '—'}</td>
                  <td className="px-4 py-3"><Badge variant={(srcV as Record<string,'blue'|'green'|'orange'|'purple'|'gray'>)[l.source] ?? 'gray'}>{srcL[l.source] ?? l.source}</Badge></td>
                  <td className="px-4 py-3"><Badge variant={(statusV as Record<string,'blue'|'green'|'orange'|'purple'|'gray'>)[l.status] ?? 'gray'}>{(statusL as Record<string,string>)[l.status] ?? l.status}</Badge></td>
                  <td className="px-4 py-3 text-sm">{l.manager}</td>
                  <td className="px-4 py-3 text-xs text-gray-400">{l.created_at}</td>
                </tr>
              ))}
              {leads.length === 0 && (
                <tr><td colSpan={7} className="py-12 text-center text-sm text-gray-400">Нет лидов</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal open={open} title="Новый лид" onClose={() => setOpen(false)}
        footer={<>
          <Button variant="ghost" onClick={() => setOpen(false)}>Отмена</Button>
          <Button onClick={() => create.mutate(form)} disabled={!form.name || create.isPending}>Создать</Button>
        </>}>
        <div className="space-y-3">
          <div><label className="field-label">Компания / Имя *</label><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="form-input" placeholder="Название компании или имя"/></div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="field-label">Контакт</label><input value={form.contact} onChange={e=>setForm({...form,contact:e.target.value})} className="form-input" placeholder="Имя Фамилия"/></div>
            <div><label className="field-label">Телефон</label><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} className="form-input"/></div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="field-label">Email</label><input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="form-input"/></div>
            <div><label className="field-label">Продукт</label><input value={form.product} onChange={e=>setForm({...form,product:e.target.value})} className="form-input" placeholder="Кредитная линия..."/></div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="field-label">Источник</label>
              <select value={form.source} onChange={e=>setForm({...form,source:e.target.value})} className="form-input">
                <option value="inbound">Входящий</option><option value="website">Сайт</option><option value="referral">Реферал</option><option value="cold">Холодный</option><option value="event">Мероприятие</option>
              </select>
            </div>
            <div><label className="field-label">Менеджер</label><input value={form.manager} onChange={e=>setForm({...form,manager:e.target.value})} className="form-input"/></div>
          </div>
        </div>
      </Modal>
    </div>
  );
}
